/* ---------- ช่วย ----------
   G(id, ชื่อ, ข้อมูล, [ขั้นย่อย…]) = ขั้นที่ขยายได้ · ขั้นย่อยเรียงต่อกันในแถวเดียว
   ขั้นย่อยเป็นข้อความ หรือ { t, sum, … } */
function G(id, t, o, list) {
  const children = list.map((x, i) => (typeof x === 'string' ? { id: `${id}-${i}`, t: x } : { id: `${id}-${i}`, ...x }));
  return { id, t, ...o, children, edges: children.slice(1).map((c, i) => [children[i].id, c.id]) };
}
